  Button(android.content.Context c,State s){super(c);state=s;setScaleType(ScaleType.FIT_CENTER);int pad=dp(this,8);setPadding(pad,pad,pad,pad);setContentDescription(Text.REPOST);setOnClickListener(v->{Object component=s.component.get();View source=s.source.get();Object handler=NativeRead.field(component,"LLLLILI");if(component!=null&&source!=null&&source.isAttachedToWindow()&&handler instanceof View.OnClickListener){Object target=NativeRead.field(component,"LLLJIL");if(target instanceof View)((View.OnClickListener)handler).onClick((View)target);else Screen.say(Text.REPOST_NOT_READY);}else Screen.say(Text.REPOST_NOT_READY);});Motion.press(this);}
